SELECT DISTINCT s.id, s.name
FROM student s


    OR (s.grade IN
    #{grade}
    AND s.status = '在读')


    OR (s.id IN (
      SELECT cs.student_id FROM class_student cs
      WHERE cs.status = '在读' AND cs.class_id IN
      #{classId}
    ))


    OR (s.id IN
    #{studentId}
    )


ORDER BY s.name
